  1→'use client';
  2→
  3→import { useState, useEffect } from 'react';
  4→import Link from 'next/link';
  5→import {
  6→  getProcessPostsBySection,
  7→  sectionLabels,
  8→  sectionDescriptions,
  9→  type ProcessSection,
 10→  type ProcessPost
 11→} from '@/lib/process-posts';
 12→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
 13→
 14→/**
 15→ * PROCESS Page — Flat Section Layout
 16→ *
 17→ * Two sections, all visible (no accordion):
 18→ * 1. Tools — Production tools (strongest section, shown first)
 19→ * 2. Explorations — Case studies + research merged
 20→ *
 21→ * Card grid: 2-col desktop, 1-col mobile
 22→ * GitHub + version badges inline on tool cards
 23→ */
 24→
 25→const SECTIONS: ProcessSection[] = ['tools', 'explorations'];
 26→
 27→function ProcessCard({ post }: { post: ProcessPost }) {
 28→  const [isHovered, setIsHovered] = useState(false);
 29→
 30→  // Tools with GitHub link → external; everything else → internal detail page
 31→  const isExternal = !!post.githubUrl;
 32→  const href = isExternal ? post.githubUrl! : `/process/${post.slug}`;
 33→
 34→  const Wrapper = isExternal ? 'a' : Link;
 35→  const linkProps = isExternal
 36→    ? { href, target: '_blank' as const, rel: 'noopener noreferrer' as const }
 37→    : { href };
 38→
 39→  return (
 40→    <Wrapper
 41→      {...linkProps}
 42→      className="group block"
 43→      onMouseEnter={() => setIsHovered(true)}
 44→      onMouseLeave={() => setIsHovered(false)}
 45→      style={{ textDecoration: 'none' }}
 46→    >
 47→      {/* Thumbnail — full-width 16:9 */}
 48→      <div
 49→        style={{
 50→          aspectRatio: '16 / 9',
 51→          borderRadius: 'var(--radius-md)',
 52→          overflow: 'hidden',
 53→          backgroundColor: post.thumbnail ? '#1a1a1a' : 'rgba(255, 255, 255, 0.04)',
 54→          marginBottom: 'var(--space-tiny)',
 55→          display: 'flex',
 56→          alignItems: 'center',
 57→          justifyContent: 'center'
 58→        }}
 59→      >
 60→        {post.thumbnail ? (
 61→          <img
 62→            src={post.thumbnail}
 63→            alt={post.title}
 64→            loading="lazy"
 65→            style={{
 66→              width: '100%',
 67→              height: '100%',
 68→              objectFit: 'cover',
 69→              opacity: isHovered ? 1 : 0.85,
 70→              transform: isHovered ? 'scale(1.02)' : 'scale(1)',
 71→              transition: 'opacity 0.3s ease, transform 0.3s ease'
 72→            }}
 73→          />
 74→        ) : (
 75→          <svg
 76→            width="28"
 77→            height="28"
 78→            viewBox="0 0 24 24"
 79→            fill="none"
 80→            stroke="currentColor"
 81→            strokeWidth="1.5"
 82→            strokeLinecap="round"
 83→            style={{
 84→              color: isHovered ? 'rgba(255, 255, 255, 0.25)' : 'rgba(255, 255, 255, 0.12)',
 85→              transition: 'color 200ms ease'
 86→            }}
 87→          >
 88→            <path d="M6 6L18 18M6 18L18 6" />
 89→          </svg>
 90→        )}
 91→      </div>
 92→
 93→      {/* Title */}
 94→      <h3
 95→        style={{
 96→          color: isHovered ? 'var(--grey-50)' : 'var(--text-primary)',
 97→          fontFamily: 'var(--font-display)',
 98→          fontWeight: 400,
 99→          fontSize: '16px',
100→          letterSpacing: '0.01em',
101→          lineHeight: 1.3,
102→          marginBottom: '6px',
103→          transition: 'color 0.25s ease'
104→        }}
105→      >
106→        {post.title}
107→      </h3>
108→
109→      {/* Excerpt — 2 lines max */}
110→      <p
111→        style={{
112→          color: 'var(--grey-500)',
113→          fontFamily: 'var(--font-display)',
114→          fontWeight: 400,
115→          fontSize: '14px',
116→          lineHeight: 1.6,
117→          display: '-webkit-box',
118→          WebkitLineClamp: 2,
119→          WebkitBoxOrient: 'vertical',
120→          overflow: 'hidden',
121→          marginBottom: '0'
122→        }}
123→      >
124→        {post.excerpt}
125→      </p>
126→
127→      {/* Meta row — version + GitHub + tags */}
128→      <div className="flex flex-wrap items-center" style={{ gap: '8px', marginTop: '10px' }}>
129→        {post.version && (
130→          <span
131→            style={{
132→              color: 'var(--text-dim)',
133→              fontFamily: 'var(--font-display)',
134→              fontSize: '11px',
135→              fontWeight: 500,
136→              letterSpacing: '0.08em',
137→              textTransform: 'uppercase'
138→            }}
139→          >
140→            v{post.version}
141→          </span>
142→        )}
143→        {post.githubUrl && (
144→          <svg
145→            width="14"
146→            height="14"
147→            viewBox="0 0 24 24"
148→            fill="currentColor"
149→            style={{ color: 'var(--text-dim)' }}
150→            aria-label="Available on GitHub"
151→          >
152→            <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z" />
153→          </svg>
154→        )}
155→        {/* Tags — Pentagram discipline tag pattern */}
156→        {post.tags && post.tags.slice(0, 3).map((tag) => (
157→          <span
158→            key={tag}
159→            style={{
160→              color: 'var(--grey-600)',
161→              fontFamily: 'var(--font-display)',
162→              fontSize: '11px',
163→              fontWeight: 400,
164→              letterSpacing: '0.02em'
165→            }}
166→          >
167→            {tag}
168→          </span>
169→        ))}
170→      </div>
171→    </Wrapper>
172→  );
173→}
174→
175→export default function ProcessPage() {
176→  const [introVisible, setIntroVisible] = useState(false);
177→  const prefersReducedMotion = usePrefersReducedMotion();
178→
179→  // Trigger intro animation on mount
180→  useEffect(() => {
181→    const timer = setTimeout(() => setIntroVisible(true), 100);
182→    return () => clearTimeout(timer);
183→  }, []);
184→
185→  return (
186→    <div className="min-h-screen" style={{ backgroundColor: '#141414' }}>
187→      <main
188→        className="mx-auto pb-32"
189→        style={{
190→          maxWidth: 'var(--max-content-width)',
191→          paddingTop: 'clamp(100px, 8vw + 60px, 180px)',
192→          paddingLeft: 'var(--side-padding)',
193→          paddingRight: 'var(--side-padding)'
194→        }}
195→      >
196→        {/* Hero Statement */}
197→        <section className="mb-12 sm:mb-[76px]">
198→          <h1
199→            style={{
200→              color: '#a0a0a0',
201→              fontFamily: 'var(--font-display)',
202→              fontWeight: 400,
203→              fontSize: 'clamp(22px, 3.5vw, 38px)',
204→              lineHeight: 1.3,
205→              letterSpacing: '0.01em',
206→              maxWidth: '900px',
207→              opacity: introVisible ? 1 : 0,
208→              transform: introVisible ? 'translateY(0)' : 'translateY(30px)',
209→              transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms, transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms'
210→            }}
211→          >
212→            Behind the final frame: tools built, problems solved, and the thinking that shapes the work.
213→          </h1>
214→        </section>
215→
216→        {/* Sections — flat, all visible */}
217→        <div
218→          style={{
219→            opacity: introVisible ? 1 : 0,
220→            transform: introVisible ? 'translateY(0)' : 'translateY(20px)',
221→            transition: prefersReducedMotion ? 'none' : 'opacity 550ms ease 200ms, transform 550ms ease 200ms'
222→          }}
223→        >
224→          {SECTIONS.map((section) => {
225→            const posts = getProcessPostsBySection(section);
226→            if (posts.length === 0) return null;
227→
228→            return (
229→              <section key={section} style={{ marginBottom: 'var(--space-section, 120px)' }}>
230→                {/* Section Header */}
231→                <div style={{ marginBottom: 'var(--space-sm)' }}>
232→                  <h2
233→                    style={{
234→                      color: 'var(--text-primary)',
235→                      fontFamily: 'var(--font-display)',
236→                      fontWeight: 400,
237→                      fontSize: 'clamp(22px, 2.2vw, 28px)',
238→                      lineHeight: 1.15,
239→                      letterSpacing: '0.005em',
240→                      marginBottom: '10px'
241→                    }}
242→                  >
243→                    {sectionLabels[section]}
244→                  </h2>
245→                  <p
246→                    style={{
247→                      color: 'var(--grey-500)',
248→                      fontFamily: 'var(--font-display)',
249→                      fontWeight: 400,
250→                      fontSize: '15px',
251→                      lineHeight: 1.5,
252→                      maxWidth: '600px'
253→                    }}
254→                  >
255→                    {sectionDescriptions[section]}
256→                  </p>
257→                </div>
258→
259→                {/* Card Grid — 2-col desktop, 1-col mobile */}
260→                <div
261→                  className="grid grid-cols-1 md:grid-cols-2"
262→                  style={{ gap: 'clamp(24px, 3vw, 40px)' }}
263→                >
264→                  {posts.map((post) => (
265→                    <ProcessCard key={post.id} post={post} />
266→                  ))}
267→                </div>
268→              </section>
269→            );
270→          })}
271→        </div>
272→      </main>
273→    </div>
274→  );
275→}
