105→// Light table warm-up effect configuration (2x faster)
106→const WARMUP_CONFIG = {
107→  staggerMin: 10,           // Min delay between photos appearing (ms)
108→  staggerMax: 40,           // Max delay between photos appearing (ms)
109→  totalDuration: 1000,      // Approximate total warm-up time (ms)
110→};
111→
112→// Cascading glow effect configuration (runs after warm-up) - 2x faster
113→const GLOW_CONFIG = {
114→  initialDelay: 750,        // Delay after warm-up before glow starts (ms)
115→  staggerDelay: 30,         // Delay between each photo lighting up (ms)
116→  glowDuration: 1250,       // How long each photo stays illuminated (ms)
117→  pauseBetweenWaves: 2000,  // Pause before next cascade wave (ms)
118→  photosPerWave: 12,        // How many photos light up per wave
119→};
120→
121→export default function PhotographyPage() {
122→  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
123→  const [isTransitioning, setIsTransitioning] = useState(false);
124→  const [slideshowVisible, setSlideshowVisible] = useState(false);
125→  const [glowingPhotos, setGlowingPhotos] = useState<Set<number>>(new Set());
126→  const [warmedUpPhotos, setWarmedUpPhotos] = useState<Set<number>>(new Set());
127→  const [isWarmupComplete, setIsWarmupComplete] = useState(false);
128→  const [isDesktop, setIsDesktop] = useState(false);
129→  const [isMounted, setIsMounted] = useState(false);
130→
131→  // Track mount state to prevent layout shift
132→  useEffect(() => {
133→    setIsMounted(true);
134→  }, []);
135→
136→  // Light table warm-up effect - photos appear randomly like a warming light table
137→  useEffect(() => {
138→    if (!isMounted) return;
139→
140→    const timeouts: NodeJS.Timeout[] = [];
141→
142→    // Create randomized order for photos to appear
143→    const indices = Array.from({ length: photos.length }, (_, i) => i);
144→    const shuffled = indices.sort(() => Math.random() - 0.5);
145→
146→    // Calculate stagger delays that add up to roughly totalDuration
147→    let currentDelay = 50; // Small initial delay (2x faster)
148→
149→    shuffled.forEach((photoIndex, i) => {
150→      const randomStagger = WARMUP_CONFIG.staggerMin +
151→        Math.random() * (WARMUP_CONFIG.staggerMax - WARMUP_CONFIG.staggerMin);
152→
153→      currentDelay += randomStagger;
154→
155→      const timeout = setTimeout(() => {
156→        setWarmedUpPhotos(prev => {
157→          const next = new Set(prev);
158→          next.add(photoIndex);
159→          return next;
160→        });
161→      }, currentDelay);
162→
163→      timeouts.push(timeout);
164→    });
165→
166→    // Mark warm-up as complete after all photos have appeared
167→    const completeTimeout = setTimeout(() => {
168→      setIsWarmupComplete(true);
169→    }, currentDelay + 250);
170→
171→    timeouts.push(completeTimeout);
172→
173→    return () => {
174→      timeouts.forEach(t => clearTimeout(t));
175→    };
176→  }, [isMounted]);
177→
178→  // Detect if device supports hover (desktop)
179→  useEffect(() => {
180→    const mediaQuery = window.matchMedia('(hover: hover) and (pointer: fine)');
181→    setIsDesktop(mediaQuery.matches);
182→
183→    const handler = (e: MediaQueryListEvent) => setIsDesktop(e.matches);
184→    mediaQuery.addEventListener('change', handler);
185→    return () => mediaQuery.removeEventListener('change', handler);
186→  }, []);
187→
188→  // Cascading light effect - photos illuminate in waves with staggered timing
189→  // Only starts after warm-up is complete
190→  useEffect(() => {
191→    if (!isDesktop || selectedIndex !== null || !isWarmupComplete) return;
192→
193→    const timeouts: NodeJS.Timeout[] = [];
194→    let waveTimeout: NodeJS.Timeout | null = null;
195→
196→    const startCascadeWave = () => {
197→      // Clear any existing timeouts
198→      timeouts.forEach(t => clearTimeout(t));
199→      timeouts.length = 0;
200→
201→      // Pick random starting positions for this wave
202→      const availableIndices = Array.from({ length: photos.length }, (_, i) => i);
203→      const shuffled = availableIndices.sort(() => Math.random() - 0.5);
204→      const wavePhotos = shuffled.slice(0, GLOW_CONFIG.photosPerWave);
205→
206→      // Cascade: light up each photo with staggered delay
207→      wavePhotos.forEach((photoIndex, i) => {
208→        // Stagger the turn-on
209→        const turnOnTimeout = setTimeout(() => {
210→          setGlowingPhotos(prev => {
211→            const next = new Set(prev);
212→            next.add(photoIndex);
213→            return next;
214→          });
215→        }, i * GLOW_CONFIG.staggerDelay);
216→
217→        timeouts.push(turnOnTimeout);
218→
219→        // Stagger the turn-off (same order, after glow duration)
220→        const turnOffTimeout = setTimeout(() => {
221→          setGlowingPhotos(prev => {
222→            const next = new Set(prev);
223→            next.delete(photoIndex);
224→            return next;
225→          });
226→        }, i * GLOW_CONFIG.staggerDelay + GLOW_CONFIG.glowDuration);
227→
228→        timeouts.push(turnOffTimeout);
229→      });
230→
231→      // Schedule next wave after this one completes
232→      const totalWaveDuration =
233→        (GLOW_CONFIG.photosPerWave * GLOW_CONFIG.staggerDelay) +
234→        GLOW_CONFIG.glowDuration +
235→        GLOW_CONFIG.pauseBetweenWaves;
236→
237→      waveTimeout = setTimeout(startCascadeWave, totalWaveDuration);
238→    };
239→
240→    // Start after initial delay
241→    const initialTimeout = setTimeout(startCascadeWave, GLOW_CONFIG.initialDelay);
242→
243→    return () => {
244→      clearTimeout(initialTimeout);
245→      if (waveTimeout) clearTimeout(waveTimeout);
246→      timeouts.forEach(t => clearTimeout(t));
247→      setGlowingPhotos(new Set());
248→    };
249→  }, [isDesktop, selectedIndex, isWarmupComplete]);
