  3→import { useEffect, useRef, useMemo } from 'react';
  4→import { ProjectCard } from './ProjectCard';
  5→import { VideoThumbnailManager } from './VideoThumbnailManager';
  6→import type { Project } from '@/lib/projects';
  7→import { useIsMobile } from '@/lib/hooks/useIsMobile';
