 3→import { useEffect, useRef } from 'react';
 4→import type { VimeoPlayerType as Player } from '@/lib/vimeo';
 5→import { loadVimeoPlayer } from '@/lib/vimeo';
 6→
 7→interface EmbeddedVideoPlayerProps {
 8→  videoId: string;
 9→  videoHash?: string; // Privacy hash for private Vimeo videos
10→}
11→
12→export function EmbeddedVideoPlayer({ videoId, videoHash }: EmbeddedVideoPlayerProps) {
13→  const playerRef = useRef<HTMLDivElement>(null);
14→  const vimeoPlayerRef = useRef<Player | null>(null);
15→
16→  useEffect(() => {
17→    if (!playerRef.current) return;
18→
19→    // Always use URL format for consistent embed behavior across all videos
20→    // URL format works better with Vimeo's embed domain restrictions
21→    const videoUrl = videoHash
22→      ? `https://vimeo.com/${videoId}/${videoHash}`
23→      : `https://vimeo.com/${videoId}`;
24→
25→    let isMounted = true;
26→
27→    const initPlayer = async () => {
28→      const VimeoPlayer = await loadVimeoPlayer();
29→      if (!isMounted || !playerRef.current) return;
30→
31→      vimeoPlayerRef.current = new VimeoPlayer(playerRef.current, {
32→        url: videoUrl as `https://vimeo.com/${string}`,
33→        width: 1280,
34→        responsive: true,
35→        autoplay: false,
36→        color: '6a6a6a',
37→        controls: true
38→      });
39→    };
40→
41→    initPlayer();
42→
43→    return () => {
44→      isMounted = false;
45→      vimeoPlayerRef.current?.destroy();
46→    };
47→  }, [videoId, videoHash]);
48→
49→  return (
50→    <div
51→      ref={playerRef}
52→      className="w-full project-video-player"
53→      style={{
54→        aspectRatio: '16/9',
55→        borderRadius: '6px',
56→        overflow: 'hidden'
57→      }}
58→    />
59→  );
60→}
